import{_ as t,o as a,c as i,a0 as o}from"./chunks/framework.Bmhw_dvp.js";const p=JSON.parse('{"title":"YouTube Integration","description":"OAuth tokens, metadata syncing, and playlist management specs.","frontmatter":{"isInternal":true,"type":"Specification","title":"YouTube Integration","description":"OAuth tokens, metadata syncing, and playlist management specs.","tags":["features","specs","architecture"]},"headers":[],"relativePath":"specs/features/youtube_integration.md","filePath":"specs/features/youtube_integration.md"}'),n={name:"specs/features/youtube_integration.md"};function s(l,e,r,c,u,d){return a(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="youtube-integration-technical-specification" tabindex="-1">YouTube Integration Technical Specification <a class="header-anchor" href="#youtube-integration-technical-specification" aria-label="Permalink to &quot;YouTube Integration Technical Specification&quot;">​</a></h1><h2 id="_1-overview" tabindex="-1">1. Overview <a class="header-anchor" href="#_1-overview" aria-label="Permalink to &quot;1. Overview&quot;">​</a></h2><p>The YouTube integration allows users to publish videos directly to their channels without downloading large MP4 files locally, streamlining the &quot;faceless channel&quot; workflow.</p><h2 id="_2-oauth-authentication" tabindex="-1">2. OAuth Authentication <a class="header-anchor" href="#_2-oauth-authentication" aria-label="Permalink to &quot;2. OAuth Authentication&quot;">​</a></h2><ul><li>Uses Google Identity Services to request <code>https://www.googleapis.com/auth/youtube.upload</code>.</li><li>The backend stores the <code>refresh_token</code> securely in Firestore/Secret Manager.</li><li>An auto-renewing engine intercepts API calls; if a token is expired, it silently fetches a new access token before proceeding.</li></ul><h2 id="_3-direct-video-publishing" tabindex="-1">3. Direct Video Publishing <a class="header-anchor" href="#_3-direct-video-publishing" aria-label="Permalink to &quot;3. Direct Video Publishing&quot;">​</a></h2><ul><li><strong>GCS to YouTube</strong>: Instead of uploading from the browser (which can crash on large files), the client triggers a Cloud Function. The Function streams the rendered <code>.mp4</code> directly from Google Cloud Storage to the YouTube Data API v3.</li><li><strong>Resumable Uploads</strong>: Uses YouTube&#39;s resumable upload protocol to handle large files and network interruptions.</li></ul><h2 id="_4-metadata-sync-playlists" tabindex="-1">4. Metadata Sync &amp; Playlists <a class="header-anchor" href="#_4-metadata-sync-playlists" aria-label="Permalink to &quot;4. Metadata Sync &amp; Playlists&quot;">​</a></h2><ul><li><strong>Dual-Mode Publish UI</strong>: Users can publish a new video, or &quot;Sync&quot; metadata (title, description, tags, custom thumbnail) to an existing video ID.</li><li><strong>Playlists</strong>: Project-level settings allow binding a Sanjeev AI Project to a specific YouTube Playlist ID. New uploads automatically append to this playlist.</li></ul>',9)])])}const g=t(n,[["render",s]]);export{p as __pageData,g as default};
